public 
enum XRestError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {

    
    
    /**
     * The selected environment is unsafe and `confirmed` was false.
     */
    case ConfirmationRequired(environment: String
    )
    case NotFound(message: String
    )
    case InvalidInput(message: String
    )
    case Io(message: String
    )
    case Http(message: String
    )
    case Preflight(message: String
    )
    /**
     * The workspace was written by a newer XRest.
     */
    case UnsupportedFormat(found: UInt32, supported: UInt32
    )
    case MissingSecrets(keys: [String]
    )
    /**
     * A git command failed; `message` is git's own error text (or "git not found").
     */
    case Git(message: String
    )
    case NotImplemented(message: String
    )

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

#if compiler(>=6)
extension XRestError: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeXRestError: FfiConverterRustBuffer {
    typealias SwiftType = XRestError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> XRestError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .ConfirmationRequired(
            environment: try FfiConverterString.read(from: &buf)
            )
        case 2: return .NotFound(
            message: try FfiConverterString.read(from: &buf)
            )
        case 3: return .InvalidInput(
            message: try FfiConverterString.read(from: &buf)
            )
        case 4: return .Io(
            message: try FfiConverterString.read(from: &buf)
            )
        case 5: return .Http(
            message: try FfiConverterString.read(from: &buf)
            )
        case 6: return .Preflight(
            message: try FfiConverterString.read(from: &buf)
            )
        case 7: return .UnsupportedFormat(
            found: try FfiConverterUInt32.read(from: &buf), 
            supported: try FfiConverterUInt32.read(from: &buf)
            )
        case 8: return .MissingSecrets(
            keys: try FfiConverterSequenceString.read(from: &buf)
            )
        case 9: return .Git(
            message: try FfiConverterString.read(from: &buf)
            )
        case 10: return .NotImplemented(
            message: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: XRestError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .ConfirmationRequired(environment):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(environment, into: &buf)
            
        
        case let .NotFound(message):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .InvalidInput(message):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .Io(message):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .Http(message):
            writeInt(&buf, Int32(5))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .Preflight(message):
            writeInt(&buf, Int32(6))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .UnsupportedFormat(found,supported):
            writeInt(&buf, Int32(7))
            FfiConverterUInt32.write(found, into: &buf)
            FfiConverterUInt32.write(supported, into: &buf)
            
        
        case let .MissingSecrets(keys):
            writeInt(&buf, Int32(8))
            FfiConverterSequenceString.write(keys, into: &buf)
            
        
        case let .Git(message):
            writeInt(&buf, Int32(9))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .NotImplemented(message):
            writeInt(&buf, Int32(10))
            FfiConverterString.write(message, into: &buf)
            
        }
    }
}


